#!/usr/bin/env python3
"""Run from project root: python3 fix_polish.py"""
import base64, os, sys
if not os.path.exists("app"): sys.exit(1)
content = base64.b64decode("").decode("utf-8")
os.makedirs("app/terminal", exist_ok=True)
open("app/terminal/page.tsx", "w", encoding="utf-8", newline="\n").write(content)
print(f"WRITTEN  app/terminal/page.tsx  ({len(content.splitlines())} lines)")
print("\nRun: npm run build && git add app/terminal/page.tsx && git commit -m \"polish: protocol OS strip, sharper hero, live indicators, RWA differentiation\" && git push origin main")
